import fs from 'node:fs';
const file = process.argv[2];
const maxTxt = Number(process.argv[3] || 900);
const lines = fs.readFileSync(file, 'utf8').split('\n').filter(Boolean);
let prev = null;
for (const [i, l] of lines.entries()) {
  let e; try { e = JSON.parse(l); } catch { continue; }
  const ts = e.timestamp || e.ts || '';
  const t = ts ? new Date(ts) : null;
  let gap = '';
  if (t && prev) { const d = (t - prev) / 1000; if (d >= 20) gap = `  [+${d.toFixed(0)}s]`; }
  if (t) prev = t;
  const role = e.type || e.role || '?';
  const m = e.message || e;
  const content = m.content;
  const short = ts ? ts.slice(5, 19) : '';
  if (typeof content === 'string') {
    console.log(`\n#${i} ${short} ${role}${gap}: ${content.slice(0, maxTxt)}`);
  } else if (Array.isArray(content)) {
    for (const c of content) {
      if (c.type === 'text') console.log(`\n#${i} ${short} ${role}${gap} TEXT: ${c.text.slice(0, maxTxt)}`);
      else if (c.type === 'thinking') console.log(`\n#${i} ${short} ${role}${gap} THINK: ${(c.thinking||'').slice(0, 400)}`);
      else if (c.type === 'tool_use') console.log(`#${i} ${short}${gap} TOOL ${c.name}: ${JSON.stringify(c.input).slice(0, 300)}`);
      else if (c.type === 'tool_result') {
        const txt = typeof c.content === 'string' ? c.content : JSON.stringify(c.content);
        console.log(`#${i} ${short}${gap} RESULT: ${(txt||'').slice(0, 220)}`);
      }
    }
  } else {
    console.log(`\n#${i} ${short} ${role}${gap} ${JSON.stringify(e).slice(0, 300)}`);
  }
}

