import { finding } from '../../../shared/engine/checks/helpers/findings.mjs';

// `.github/workflows/chrome-extension-daily-release.yml` is VENDORED from the
// chrome-extension-release pack, and this repo's copy is deliberately NOT
// byte-identical to that stub: #241 added a step to the `bump` job that aligns
// the repo-root package.json to the bumped version inside the same commit. It is
// load-bearing — the release config only bumps `manifest_path` and
// `package_json_path`, so without it the root file falls behind after every
// daily release and both the `sharedConstants` version entry in
// .claudinite-checks.json and `cer/version-sync` go BLOCKING.
//
// The delta is fragile in a specific, repeating way: the pack's
// `chrome-release-vendoring` migration MATERIALIZES this path — an unconditional
// verbatim overwrite from the stub, with no per-repo exemption seam (unlike a
// check finding, which .claudinite-checks.json can `accept`). Baselining
// re-attempts that write every cycle, so any agent that lands the withheld file
// mechanically deletes the step and silently re-opens the drift #241 closed.
// Issue #245 is the open decision on the real fix (teach release.config the root
// file, or give materialize an extension point); until it lands, this check is
// what makes the deletion loud instead of silent. When #245 resolves, delete
// this rule with the step.
//
// It keys on the BEHAVIOUR, not the step's label: the align step is the only
// place the workflow names the repo-root `package.json` as a literal file, since
// the stub reaches the two release-config paths through
// `${{ steps.cfg.outputs.* }}` only. So renaming or rewording the step keeps
// this silent, and only actually dropping the root-file write fires it.
const WORKFLOW = '.github/workflows/chrome-extension-daily-release.yml';

// The quoted literal the align step's inline node script reads and writes.
const ROOT_PACKAGE_JSON = /(["'])package\.json\1/;

const rule = {
  id: 'tldr/release-root-version-align',
  severity: 'blocking',
  description: "The daily-release workflow must keep aligning the repo-root package.json to the bumped version — it is this repo's local delta over the vendored stub",
  doc: '.claudinite/local/packs/tldr/RULES.md',
  scope: 'world',
  why: 'the release config bumps only the manifest and extension package.json, so without this step the repo-root package.json falls behind after every daily release and the version sharedConstants entry plus cer/version-sync both go BLOCKING (#241, #245)',

  run(ctx) {
    const text = ctx.read(WORKFLOW);
    // A missing file is `cer/release-workflows`'s finding, not this one.
    if (text === null) return [];
    if (ROOT_PACKAGE_JSON.test(text)) return [];

    return [finding(rule, {
      file: WORKFLOW,
      what: 'the bump job no longer writes the repo-root package.json — the "Align the root package.json to the bumped version" step is gone, so the next daily release will bump only the two release-config paths',
      fix: `restore the step from ${'2529b63'} (PR #241) — it replaces the single \`"version": "X.Y.Z"\` token in the root package.json with \`steps.bump.outputs.version\` before the push. If it vanished after a baselining cycle, the chrome-release-vendoring materialize overwrote this file with the canon stub: re-apply the step rather than accepting the stub, and say so on #245`,
    })];
  },
};

export default rule;

// See-it-fail fixture for tldr/release-root-version-align.
//
// The two fixtures are the real files, not hand-written YAML: the repo's own
// committed workflow (which carries #241's align step) must stay silent, and the
// canon stub the `chrome-release-vendoring` materialize would overwrite it with
// must fire exactly one finding. That is the regression this rule exists for, so
// the fixture is only honest if it is that exact byte sequence.
//
// Run it directly (no npm script owns .claudinite/local/packs):
//   node --test .claudinite/local/packs/tldr/release-root-version-align.test.mjs

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { resolve, dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

import rule from './release-root-version-align.mjs';

const repoRoot = resolve(dirname(fileURLToPath(import.meta.url)), '..', '..', '..', '..');
const WORKFLOW = '.github/workflows/chrome-extension-daily-release.yml';
const STUB = '.claudinite/shared/packs/chrome-extension-release/stubs/workflows/chrome-extension-daily-release.yml';

// A minimal world context: the rule reads exactly one path.
const ctxServing = (text) => ({ read: (path) => (path === WORKFLOW ? text : null) });
const read = (path) => readFileSync(join(repoRoot, path), 'utf8');

test('silent on the repo\'s committed workflow, which carries the align step', () => {
  assert.deepEqual(rule.run(ctxServing(read(WORKFLOW))), []);
});

test('fires on the canon stub — the exact content a materialize would write', () => {
  const findings = rule.run(ctxServing(read(STUB)));
  assert.equal(findings.length, 1);
  assert.equal(findings[0].severity, 'blocking');
  assert.equal(findings[0].file, WORKFLOW);
  assert.match(findings[0].fix, /#245/);
});

test('silent when the workflow is absent — that is cer/release-workflows\' finding', () => {
  assert.deepEqual(rule.run({ read: () => null }), []);
});

